module parallel2serial (
    input clk, 
    input rst_n, 
    input [3:0] d, 
    output reg valid_out, 
    output reg dout
);
// Sequential logic for the counter and data storage
reg [3:0] data;
reg [1:0] cnt;
reg valid;
// Combinational logic for output generation
always @(*) begin
    dout = data[3];
end
// Always block triggered on the rising edge of the clock or the negative edge of the reset signal
always @(posedge clk or negedge rst_n) begin
    // Check if the reset signal is low
    if (~rst_n) begin
        // Reset the counter to 0
        cnt <= 2'b00;

        // Set the valid signal to 0
        valid <= 1'b0;
    end else begin
        // Check if the counter is equal to 3
        if (cnt == 2'b11) begin
            // Update the data register with the input data
            data <= d;

            // Reset the counter to 0
            cnt <= 2'b00;

            // Set the valid signal to 1
            valid <= 1'b1;
        end else begin
            // Rotate the data register to the left by 1 bit
            data <= {data[2:0], data[3]};

            // Increment the counter by 1
            cnt <= cnt + 1;

            // Set the valid signal to 0
            valid <= 1'b0;
        end
    end
end
// Assign the valid signal to the valid_out output
assign valid_out = valid;
endmodule
